CREATE OR REPLACE TRIGGER trg_check_salaire
BEFORE UPDATE OF salaire ON employes
FOR EACH ROW
BEGIN
    -- On interdit toute baisse de salaire !
    IF :NEW.salaire < :OLD.salaire THEN
        RAISE_APPLICATION_ERROR(-20005, 'Baisse de salaire strictement interdite !');
    END IF;
END;
/

