steps.sql:
CREATE SEQUENCE seq_articles START WITH 1 INCREMENT BY 1;

CREATE OR REPLACE TRIGGER trg_articles_autoincrement
BEFORE INSERT ON articles
FOR EACH ROW
BEGIN
    IF :NEW.id IS NULL THEN
        :NEW.id := seq_articles.NEXTVAL;
    END IF;
END;
/

-- ERREUR TABLE MUTANTE (ORA-04091) :
CREATE OR REPLACE TRIGGER trg_interdit
AFTER INSERT ON employes
FOR EACH ROW
DECLARE
    v_nb NUMBER;
BEGIN
    -- INTERDIT : on lit la table employes alors qu'elle est en cours de modification !
    SELECT COUNT(*) INTO v_nb FROM employes;
END;
